-- 0006: curated RU/KY destination content shown on public destination pages.
begin;
update public.destinations set description = '{"en":"Leafy capital with Soviet-modernist avenues at the foot of the Kyrgyz Ala-Too range. Your gateway, and the best place in the country to eat.","ru":"Зелёная столица с советскими модернистскими проспектами у подножия хребта Кыргызский Ала-Тоо. Это главные ворота страны и лучшее место для знакомства с местной кухней.","ky":"Кыргыз Ала-Тоосунун этегинде советтик модернисттик проспекттери бар жалбырактуу борбор. Бул өлкөнүн башкы дарбазасы жана жергиликтүү аш-казан менен таанышуунун эң жакшы жери."}'::jsonb, i18n = '{"ru":{"dayTitle":"Бишкек","activities":["Прогулка по Ошскому базару и уличная еда","Площадь Ала-Тоо и Дубовый парк","Государственный исторический музей"],"tips":["Такси через Яндекс Go недорогое и надёжное.","По понедельникам базары закрываются рано."],"details":{"history":"Город основан в 1825 году как кокандская крепость Пишпек; в советское время назывался Фрунзе, а с 1991 года — Бишкек.","howToGetThere":"Международный аэропорт Манас (FRU) находится примерно в 30 км к северу от центра; проще всего добраться на такси через приложение."}},"ky":{"dayTitle":"Бишкек","activities":["Ош базары жана көчө тамактары","Ала-Тоо аянты жана Дубовый парк","Мамлекеттик тарых музейи"],"tips":["Яндекс Go таксиси арзан жана ишенимдүү.","Дүйшөмбү күндөрү базарлар эрте жабылат."],"details":{"history":"Шаар 1825-жылы Кокон тышкысындай Пишпек чепи катары негизделген; совет учурунда Фрунзе, 1991-жылдан бери Бишкек деп аталат.","howToGetThere":"Манас эл аралык аэропорту (FRU) борбордон болжол менен 30 км түндүктө; эң ыңгайлуу жол — тиркеме аркылуу такси."}}}'::jsonb where id = 'bishkek';
update public.destinations set description = '{"en":"National park 40 km south of Bishkek. Juniper-lined gorge, glaciers and 4,000 m peaks within an hour of the city.","ru":"Национальный парк в 40 км к югу от Бишкека. Ущелье с арчовым лесом, ледники и четырёхтысячники всего в часе езды от города.","ky":"Бишкектен 40 км түштүктөгү улуттук парк. Арча токойлору, мөңгүлөр жана 4 000 метрлик чокулар шаардан бир саатте."}'::jsonb, i18n = '{"ru":{"dayTitle":"Пеший маршрут по ущелью Ала-Арча","activities":["Тропа к водопаду Ак-Сай","Прогулка по ущелью среди арчи","Виды на пик Корона"],"tips":["Вход в парк оплачивается наличными на КПП.","Выезжайте рано: после полудня облака часто закрывают вершины."],"details":{"history":"Охраняется как национальный парк с 1976 года.","howToGetThere":"Примерно 40 км к югу от Бишкека: около часа на такси или с частным водителем. Регулярного общественного транспорта до входа нет.","safety":"Выше границы леса погода меняется быстро; возьмите тёплые слои одежды и воду."}},"ky":{"dayTitle":"Ала-Арча капчыгайында жөө сапар","activities":["Ак-Сай шаркыратмасына жол","Арча токойлорунун арасынан сейилдик","Корона чокусунун көрүнүшү"],"tips":["Паркка кирүү акысы дарбазада накталай төлөнөт.","Эрте чыгыңыз: түштөн кийин булуттар чокуларды жаап калышы мүмкүн."],"details":{"history":"1976-жылдан бери улуттук парк катары корголот.","howToGetThere":"Бишкектен болжол менен 40 км түштүктө: такси же жеке айдоочу менен бир саат чамасында. Дарбазага чейин туруктуу коомдук транспорт жок.","safety":"Токой чегинен жогору аба ыкчам өзгөрөт; жылуу кийим жана суу алыңыз."}}}'::jsonb where id = 'ala-archa';
update public.destinations set description = '{"en":"The world''s second-largest alpine lake. The south shore is wilder and quieter than the north, with red cliffs, yurt camps and eagle hunters.","ru":"Второе по величине высокогорное озеро мира. Южный берег диковатый и спокойнее северного: красные скалы, юрточные лагеря и охотники с беркутами.","ky":"Дүйнөдөгү экинчи чоң бийик тоо көлү. Түштүк жээк түндүккө караганда кыйыр жана тынч: кызыл жарлар, боз үй лагерлери жана бүркүтчүлөр."}'::jsonb, i18n = '{"ru":{"dayTitle":"Южный берег Иссык-Куля","activities":["Купание на тихом пляже южного берега","Прогулка по берегу на закате","Посещение села мастеров по изготовлению юрт"],"tips":["В июне вода самая холодная; лучшее время для купания — с середины июля по август."],"details":{"history":"Озеро на Великом шёлковом пути; благодаря лёгкой солёности оно не замерзает даже на такой высоте.","howToGetThere":"Сёла южного берега находятся в 4–6 часах езды от Бишкека; попутные такси отправляются с Западного и Восточного автовокзалов."}},"ky":{"dayTitle":"Ысык-Көлдүн түштүк жээгинде","activities":["Түштүк жээктеги тынч пляжда сууга түшүү","Күн батарда жээгинде сейилдик","Боз үй жасоочу усталардын айылына баруу"],"tips":["Июнь айында суу эң суук; сууга түшүү үчүн эң жакшы убакыт — июлдун ортосу жана август."],"details":{"history":"Жибек жолундагы көл; жеңил туздуулугунан улам бийиктикте да катып калбайт.","howToGetThere":"Түштүк жээктеги айылдар Бишкектен унаа менен 4–6 саатте; жалпы таксилер Батыш жана Чыгыш автобекеттеринен чыгат."}}}'::jsonb where id = 'issyk-kul';
update public.destinations set description = '{"en":"North-shore resort town on Issyk-Kul, known for Bronze Age petroglyphs and summer beaches.","ru":"Курортный город на северном берегу Иссык-Куля, известный петроглифами бронзового века и летними пляжами.","ky":"Ысык-Көлдүн түндүк жээгиндеги курорт шаары; коло доорунун петроглифтери жана жайкы пляждары менен белгилүү."}'::jsonb, i18n = '{"ru":{"dayTitle":"Чолпон-Ата и петроглифы","activities":["Прогулка по полю петроглифов","Пляжный отдых после обеда","Культурный центр Рух Ордо"],"tips":["В конце июля очень людно; бронируйте жильё заранее."],"details":{"history":"Город известен полем петроглифов под открытым небом с рисунками от бронзового века и позже.","howToGetThere":"Северный берег Иссык-Куля, примерно 250 км от Бишкека, около 4 часов в пути."}},"ky":{"dayTitle":"Чолпон-Ата жана петроглифтер","activities":["Петроглифтер талаасында сейилдик","Түштөн кийин пляж","Рух Ордо маданий борбору"],"tips":["Июлдун аягында эле көп; жайгашууну алдын ала брондоюңуз."],"details":{"history":"Коло доорунан баштап жасалган сүрөттөрү бар ачык асман алдындагы петроглифтер талаасы менен белгилүү.","howToGetThere":"Ысык-Көлдүн түндүк жээгинде, Бишкектен болжол менен 250 км, жол болжол менен 4 саат."}}}'::jsonb where id = 'cholpon-ata';
update public.destinations set description = '{"en":"Trekking capital of the east, with wooden Russian houses, a Dungan mosque built without nails and the best ashlyan-fu in the country.","ru":"Столица треккинга на востоке: деревянные русские дома, дунганская мечеть без единого гвоздя и лучший ашлян-фу в стране.","ky":"Чыгыштагы треккинг борбору: жыгач орус үйлөрү, саманчылыксыз салынган дунган мечити жана өлкөдөгү эң даамдуу ашлян-фу."}'::jsonb, i18n = '{"ru":{"dayTitle":"Город Каракол","activities":["Дунганская мечеть и деревянный Свято-Троицкий собор","Воскресный рынок скота","Гастропрогулка с ашлян-фу"],"tips":["Воскресный рынок скота начинается на рассвете."],"details":{"history":"Основан в 1869 году как русский военный и торговый пост; здесь находятся деревянный Свято-Троицкий собор и дунганская мечеть без гвоздей.","howToGetThere":"Примерно 400 км от Бишкека по северному берегу, 6–7 часов в пути. Маршрутки из Бишкека ходят ежедневно."}},"ky":{"dayTitle":"Каракол шаары","activities":["Дунган мечити жана жыгач Ыйык Үч Бирдик собору","Жекшембидеги мал базары","Ашлян-фу дегустациясы"],"tips":["Жекшембидеги мал базары таң атканда башталат."],"details":{"history":"1869-жылы орус аскердик жана соода посту катары негизделген; бул жерде жыгач собор жана саманчылыксыз дунган мечити бар.","howToGetThere":"Бишкектен түндүк жээгинен болжол менен 400 км, 6–7 саат. Бишкектен маршруткалар күн сайын жүрөт."}}}'::jsonb where id = 'karakol';
update public.destinations set description = '{"en":"High valley with natural hot springs under Palatka peak, reached on foot, on horseback or by old Soviet truck.","ru":"Высокогорная долина с природными горячими источниками под пиком Палатка. Добраться можно пешком, верхом или на старом советском грузовике.","ky":"Палатка чокусунун астындагы табигый ысык булактары бар бийик өрөөн. Жөө, ат менен же эски советтик унаада жетсе болот."}'::jsonb, i18n = '{"ru":{"dayTitle":"Горячие источники Алтын-Арашан","activities":["Подъём по долине Арашан","Купание в горячих источниках","Вид на пик Палатка"],"tips":["Дорога сложная: нужен полный привод или поход около 5 часов вверх."],"details":{"culture":"Долина горячих источников, которой пользуются пастухи и треккеры.","howToGetThere":"От села Ак-Суу рядом с Караколом: трансфер на 4x4 по грубой дороге или пеший подъём 4–6 часов.","safety":"Высота около 3 000 м: поднимайтесь постепенно и берите тёплую одежду."}},"ky":{"dayTitle":"Алтын-Арашандын ысык булактары","activities":["Арашан өрөөнү менен жөө көтөрүлүү","Ысык булакта суунуу","Палатка чокусунун көрүнүшү"],"tips":["Жол татаал: 4x4 керек же жөө болжол менен 5 саат көтөрүлөсүз."],"details":{"culture":"Булактуу өрөөнтү малчылар жана жөө жүргүчтөр колдонушат.","howToGetThere":"Караколго жакын Ак-Суу айылынан: начар жол менен 4x4 же 4–6 сааттык жөө сапар.","safety":"Бийиктик болжол менен 3 000 м: акырын көтөрүлүп, жылуу кийим алыңыз."}}}'::jsonb where id = 'altyn-arashan';
update public.destinations set description = '{"en":"Red sandstone cliffs called the Seven Bulls, opening into alpine meadows grazed by horses in summer.","ru":"Красные песчаниковые скалы «Семь быков», за которыми открываются альпийские луга с пасущимися летом лошадьми.","ky":"«Жети өгүз» деп аталган кызыл кумтас жарлар; алардын артында жайында жылкылар жайылган альпийдин чөптөрү ачылат."}'::jsonb, i18n = '{"ru":{"dayTitle":"Красные скалы Джети-Огуз","activities":["Красные скалы Семи быков","Смотровая площадка у скалы Разбитое сердце","Прогулка по Долине цветов"],"tips":["Лучший свет для фотографий — ближе к закату."],"details":{"culture":"Место названо в честь красных песчаниковых скал «Семь быков»; рядом находится скала «Разбитое сердце».","howToGetThere":"Примерно в 25 км к западу от Каракола, около 40 минут на машине."}},"ky":{"dayTitle":"Жети-Өгүздүн кызыл жарлары","activities":["Жети өгүздүн кызыл жарлары","«Сынган жүрөк» жарына көрүү аянтчасы","Гүлдөр өрөөнүндө сейилдик"],"tips":["Сүрөт үчүн эң жакшы жарык — күн батары жакында."],"details":{"culture":"Кызыл кумтас «Жети өгүз» жарларынын атынан аталган; жанында «Сынган жүрөк» жары жайгашкан.","howToGetThere":"Караколдон болжол менен 25 км батышта, унаа менен 40 мүнөт чамасында."}}}'::jsonb where id = 'jeti-oguz';
update public.destinations set description = '{"en":"Alpine lake at 3,000 m ringed by summer pastures. Herders move up with their yurts from June: the purest nomad experience in the country.","ru":"Альпийское озеро на высоте 3 000 м, окружённое летними пастбищами. С июня пастухи поднимаются сюда с юртами — самый чистый опыт кочевой жизни в стране.","ky":"3 000 метр бийиктикте жайлоо чөптөрү менен курчалган альпийдин көлү. Июнь айынан тарта малчылар боз үйлөрү менен көтөрүлүшөт — өлкөдөгү эң таза көчмөн тажрыйбасы."}'::jsonb, i18n = '{"ru":{"dayTitle":"Ночи с пастухами на Сон-Куле","activities":["Вечер в семье пастухов","Рассвет над озером","Фотографирование Млечного Пути"],"tips":["Электросети нет; лагеря работают от солнечных панелей.","Дороги обычно открыты примерно с июня по сентябрь."],"details":{"culture":"Летнее пастбище (джайлоо), где пастухи живут в юртах с июня по сентябрь.","howToGetThere":"Через Кочкор по горным дорогам, обычно проходимым только летом; рекомендуется 4x4.","safety":"Мобильной связи нет; ночи могут быть почти морозными даже в июле."}},"ky":{"dayTitle":"Соң-Көлдө малчылар менен түнөлөр","activities":["Малчы үй-бүлөсү менен кеч","Көлдүн үстүнөн таң аткан көрүнүш","Саман жолун сүрөткө тартуу"],"tips":["Электр тармагы жок; лагерлер күн панелдери менен иштейт.","Жолдор болжол менен июнь–сентябрь айларында ачык."],"details":{"culture":"Малчылар июнь–сентябрда боз үйлөрдө жашаган жайлоо (жайыт).","howToGetThere":"Кочкор аркылуу тоо жолдору менен; адатта жайда гана өтсө болот. 4x4 сунушталат.","safety":"Мобилдик байланыш жок; июль айында да түнкүсүн муздак болушу мүмкүн."}}}'::jsonb where id = 'song-kul';
update public.destinations set description = '{"en":"Stone caravanserai on a Silk Road branch, hidden in a quiet valley near the Chinese border.","ru":"Каменный караван-сарай на одном из ответвлений Шёлкового пути, спрятанный в тихой долине у границы с Китаем.","ky":"Кытай чек арасына жакын тынч өрөөндө жайгашкан Жибек жолунун бутагындагы таш кербен-сарайы."}'::jsonb, i18n = '{"ru":{"dayTitle":"Караван-сарай Таш-Рабат","activities":["Каменный караван-сарай XV века","Конная прогулка к перевалу Чатыр-Куль","Ночь в юрте в долине"],"tips":["Уединённое место: удобно совместить с Нарыном и Чатыр-Кулем."],"details":{"history":"Каменный караван-сарай на ответвлении Шёлкового пути, обычно датируется XV веком.","howToGetThere":"Примерно в 90 км к югу от Нарына по дороге к перевалу Торугарт."}},"ky":{"dayTitle":"Таш-Рабат кербен-сарайы","activities":["XV кылымдагы таш кербен-сарайы","Чатыр-Көл ашуусуна ат менен баруу","Өрөөндө боз үйдө түнөө"],"tips":["Кыйыр жер: Нарын жана Чатыр-Көл менен бирге пландаңыз."],"details":{"history":"Жибек жолунун бутагындагы таш кербен-сарайы, адатта XV кылымга таандык деп эсептелет.","howToGetThere":"Нарындан түштүккө карай болжол менен 90 км, Торугарт ашуусуна барар жолдо."}}}'::jsonb where id = 'tash-rabat';
update public.destinations set description = '{"en":"Long river town, the practical hub for the inner Tien Shan and the road to Tash Rabat.","ru":"Длинный речной город и практичная база для путешествий по внутреннему Тянь-Шаню и дороге к Таш-Рабату.","ky":"Дарыя боюнда созулган шаар; ички Теңир-Тоо жана Таш-Рабат жолу үчүн ыңгайлуу борбор."}'::jsonb, i18n = '{"ru":{"dayTitle":"Нарын","activities":["Прогулка по набережной реки Нарын","Областной музей","Ущелье Салкын-Тор"],"tips":["Хорошее место, чтобы пополнить наличные и топливо."],"details":{"howToGetThere":"Около 5 часов езды от Бишкека; это база для поездок к Таш-Рабату и дороге на Торугарт."}},"ky":{"dayTitle":"Нарын","activities":["Нарын дарыясынын жээгинде сейилдик","Облустук музей","Салкын-Тор капчыгайы"],"tips":["Накталай акча жана күйүүчү май алуу үчүн ыңгайлуу жер."],"details":{"howToGetThere":"Бишкектен унаа менен болжол менен 5 саат; Таш-Рабат жана Торугарт жолу үчүн негизги пункт."}}}'::jsonb where id = 'naryn';
update public.destinations set description = '{"en":"One of Central Asia''s oldest cities, centered on the UNESCO-listed Sulaiman-Too mountain and a vast bazaar.","ru":"Один из древнейших городов Центральной Азии, выросший вокруг священной горы Сулайман-Тоо из списка ЮНЕСКО и огромного базара.","ky":"Борбордук Азиядагы эң байыркы шаарлардын бири; ЮНЕСКО тизмесиндеги Сулайман-Тоо тоосу жана чоң базар тегерегинде жайгашкан."}'::jsonb, i18n = '{"ru":{"dayTitle":"Старый город Оша","activities":["Священная гора Сулайман-Тоо","Базар Джайма","Обед с пловом"],"tips":["На Сулайман-Тоо одевайтесь сдержанно."],"details":{"history":"Один из старейших городов Центральной Азии. Гора Сулайман-Тоо входит в список Всемирного наследия ЮНЕСКО (2009).","howToGetThere":"Из Бишкека ежедневно летают самолёты около часа; автомобильная дорога через горы занимает 10 и более часов."}},"ky":{"dayTitle":"Оштун эски шаары","activities":["Ыйык Сулайман-Тоо тоосу","Жайма базары","Палуудан түшкү тамак"],"tips":["Сулайман-Тоодо жөнөкөй жана сактуу кийиниңиз."],"details":{"history":"Борбордук Азиядагы эң байыркы шаарлардын бири. Сулайман-Тоо тоосу ЮНЕСКОнун Дүйнөлүк мурас тизмесине кирет (2009).","howToGetThere":"Бишкектен күн сайын болжол менен бир сааттык учуулар бар; унаа менен тоолуу жол 10 сааттан ашык созулат."}}}'::jsonb where id = 'osh';
update public.destinations set description = '{"en":"Village in the world''s largest wild walnut forest, with waterfalls and community homestays.","ru":"Село в самом большом диком ореховом лесу мира: водопады и общинные гостевые дома.","ky":"Дүйнөдөгү эң чоң жапайы жаңгак токойундагы айыл: шаркыратмалар жана коомдук мейман үйлөр."}'::jsonb, i18n = '{"ru":{"dayTitle":"Ореховый лес Арсланбоба","activities":["Самый большой в мире ореховый лес","Большой и малый водопады","Домашняя кухня в гостевом доме"],"tips":["Гидов организует местный офис общинного туризма."],"details":{"culture":"Село окружено одним из крупнейших диких ореховых лесов мира.","howToGetThere":"Из Джалал-Абада на попутном такси, примерно 2–3 часа."}},"ky":{"dayTitle":"Арстанбаптын жаңгак токою","activities":["Дүйнөдөгү эң чоң жаңгак токою","Чоң жана кичине шаркыратмалар","Мейман үйдө үй тамагы"],"tips":["Гиддерди жергиликтүү коомдук туризм кеңсеси уюштурат."],"details":{"culture":"Айыл дүйнөдөгү эң чоң жапайы жаңгак токойлорунун биринин ичинде жайгашкан.","howToGetThere":"Жалал-Абаддан жалпы такси менен болжол менен 2–3 саат."}}}'::jsonb where id = 'arslanbob';
update public.destinations set description = '{"en":"UNESCO biosphere reserve with a deep turquoise lake set in forested mountains.","ru":"Биосферный резерват ЮНЕСКО с глубоким бирюзовым озером среди лесистых гор.","ky":"Токойлук тоолордун ортосундагы терең, бадия түстүү көлү бар ЮНЕСКО биосфералык резерваты."}'::jsonb, i18n = '{"ru":{"dayTitle":"Заповедник Сары-Челек","activities":["Тропа к смотровой площадке над озером","Прогулка по биосферному резервату","Лодка к скрытым озёрам"],"tips":["Входной сбор резервата оплачивается на въезде."],"details":{"culture":"Озеро находится внутри биосферного резервата ЮНЕСКО.","howToGetThere":"Труднодоступное место: из Джалал-Абада или Таш-Кумыра через село Аркыт; поездка занимает почти целый день."}},"ky":{"dayTitle":"Сары-Челек резерваты","activities":["Көлдүн көрүнүшүнө барар жол","Биосфералык резерватта сейилдик","Жашыруун көлдөргө кайык сапары"],"tips":["Резерваттын кирүү акысы кире бериште төлөнөт."],"details":{"culture":"Көл ЮНЕСКОнун биосфералык резерватынын ичинде жайгашкан.","howToGetThere":"Кыйыр жер: Жалал-Абад же Таш-Көмүр аркылуу Аркыт айылы аркылуу; жол дээрлик бир күн."}}}'::jsonb where id = 'sary-chelek';
update public.destinations set description = '{"en":"Broad high valley between two ranges, full of summer yurts, on the Bishkek to Osh highway.","ru":"Широкая высокогорная долина между двумя хребтами, летом полная юрт. Находится на трассе Бишкек—Ош.","ky":"Эки кырка тоонун ортосундагы кенен бийик өрөөн; жайында боз үйлөр көп. Бишкек—Ош жолунда жайгашкан."}'::jsonb, i18n = '{"ru":{"dayTitle":"Долина Суусамыр","activities":["Высокогорные пастбища долины","Дегустация кумыса у пастухов","Дорога через перевал Тоо-Ашуу"],"tips":["Тоннель Тоо-Ашуу может закрываться в плохую погоду."],"details":{"howToGetThere":"Высокогорная долина на трассе Бишкек—Ош, примерно 3 часа от Бишкека через перевал Тоо-Ашуу."}},"ky":{"dayTitle":"Суусамыр өрөөнү","activities":["Бийик өрөөндөгү жайлоо чөптөрү","Малчылардан кымыз датуу","Тоо-Ашуу ашуусу аркылуу сапар"],"tips":["Тоо-Ашуу туннели начар аба ырайында жабылышы мүмкүн."],"details":{"howToGetThere":"Бишкек—Ош жолундагы бийик өрөөн; Бишкектен Тоо-Ашуу ашуусу аркылуу болжол менен 3 саат."}}}'::jsonb where id = 'suusamyr';
update public.destinations set description = '{"en":"\"Fairy Tale\" canyon: eroded red and ochre ridges a short walk from the lake shore.","ru":"Каньон «Сказка»: выветренные красные и охристые хребты всего в нескольких минутах ходьбы от берега озера.","ky":"«Жомок» капчыгайы: көл жээгинен бир нече мүнөттүк жерде жел менен кыспатка түшкөн кызыл жана саргыч кыркалар."}'::jsonb, i18n = '{"ru":{"dayTitle":"Каньон Сказка","activities":["Подъём по красным грядам","Виды на озеро сверху","Фотографии в золотой час"],"tips":["Наденьте обувь с хорошим сцеплением: склоны крошатся."],"details":{"culture":"«Сказочный» каньон из красных и оранжевых выветренных скальных форм.","howToGetThere":"Южный берег Иссык-Куля возле села Тосор; от главной дороги есть указанный поворот."}},"ky":{"dayTitle":"Жомок капчыгайы","activities":["Кызыл кыркалар менен жөө жүрүү","Үстүңкү жерден көлдүн көрүнүшү","Алтын саатта сүрөт тартуу"],"tips":["Туруктуу бут кийим кийиңиз: кыркалар кыйрап турат."],"details":{"culture":"Жел менен пайда болгон кызыл жана кыызыл жаратылыш формаларынын «жомок» капчыгайы.","howToGetThere":"Ысык-Көлдүн түштүк жээгинде, Тосор айылына жакын; негизги жолдон бурулуш белгиленген."}}}'::jsonb where id = 'skazka';
update public.destinations set description = '{"en":"Gorge south of the lake with waterfalls and alpine meadows, once a cosmonaut retreat.","ru":"Ущелье к югу от озера с водопадами и альпийскими лугами; раньше здесь отдыхали космонавты.","ky":"Көлдүн түштүгүндөгү шаркыратмалары жана альпийдин чөптөрү бар капчыгай; мурда космонавттардын эс алуу жери болгон."}'::jsonb, i18n = '{"ru":{"dayTitle":"Водопады Барскоона","activities":["Водопад «Слёзы леопарда»","Мемориал Гагарина","Поездка по ущелью"],"tips":["Верхняя дорога ущелья предназначена только для 4x4."],"details":{"howToGetThere":"Южный берег Иссык-Куля; дорога ущелья поднимается от села Барскоон к водопадам."}},"ky":{"dayTitle":"Барскоон шаркыратмалары","activities":["«Кабыландын көз жашы» шаркыратмасы","Гагарин эстелиги","Капчыгай менен унаа сапары"],"tips":["Капчыгайдын жогорку жолу 4x4 үчүн гана."],"details":{"howToGetThere":"Ысык-Көлдүн түштүк жээгинде; капчыгай жолу Барскоон айылынан шаркыратмаларга көтөрүлөт."}}}'::jsonb where id = 'barskoon';
update public.destinations set description = '{"en":"Remote lake filling a narrow canyon near the Chinese border. Needs a border permit and a 4x4.","ru":"Труднодоступное озеро, заполнившее узкий каньон у границы с Китаем. Нужны пограничный пропуск и полный привод.","ky":"Кытай чек арасына жакын тар капчыгайды толтурган кыйыр көл. Чек ара уруксаты жана 4x4 керек."}'::jsonb, i18n = '{"ru":{"dayTitle":"Экспедиция на Кёль-Суу","activities":["Лодка через затопленный каньон","Горная дорога по пограничной зоне"],"tips":["Нужен пограничный пропуск; оформляйте его минимум за 10 дней."],"details":{"howToGetThere":"Удалённое озеро в долине Кок-Кия у границы с Китаем; обычно добираются из Нарынской области на 4x4, затем пешком или на лодке.","safety":"Пограничная зона: требуется пропуск, который нужно оформить заранее."}},"ky":{"dayTitle":"Көл-Сууга экспедиция","activities":["Сууга калкан капчыгай менен кайык сапары","Чек ара аймагындагы тоо жолу"],"tips":["Чек ара уруксаты керек; аны кеминде 10 күн мурун оформтуңуз."],"details":{"howToGetThere":"Кытай чек арасына жакын Кок-Кыя өрөөнүндөгү кыйыр көл; адатта Нарын облусунан 4x4 менен барышат, андан кийин жөө же кайык менен.","safety":"Чек ара аймагы: уруксат керек жана алдын ала оформтулушу шарт."}}}'::jsonb where id = 'kel-suu';
update public.destinations set description = '{"en":"High, windswept lake above Tash Rabat on the old caravan road. Border permit needed.","ru":"Высокое продуваемое озеро над Таш-Рабатом на старой караванной дороге. Нужен пограничный пропуск.","ky":"Таш-Рабаттын үстүндөгү эски кербен жолундагы бийик, шамалдуу көл. Чек ара уруксаты керек."}'::jsonb, i18n = '{"ru":{"dayTitle":"Чатыр-Куль","activities":["Альпийское озеро на высоте 3 500 м","Наблюдение за дикими животными и птицами"],"tips":["Нужен пропуск; езжайте с зарегистрированным туроператором."],"details":{"howToGetThere":"Рядом с перевалом Торугарт, дальше Таш-Рабата.","safety":"Пограничная зона: требуется пропуск."}},"ky":{"dayTitle":"Чатыр-Көл","activities":["3 500 метр бийиктиктеги альпийдин көлү","Жапайы жаныбарларды жана куштарды байкоо"],"tips":["Уруксат керек; катталган туроператор менен барыңыз."],"details":{"howToGetThere":"Таш-Рабаттан ары, Торугарт ашуусуна жакын.","safety":"Чек ара аймагы: уруксат керек."}}}'::jsonb where id = 'chatyr-kul';
update public.destinations set description = '{"en":"Deep red canyons near the Boom gorge, spectacular and surprisingly empty.","ru":"Глубокие красные каньоны возле Боомского ущелья — эффектные и удивительно малолюдные.","ky":"Боом капчыгайына жакын терең кызыл капчыгайлар — таң калыштуу жана күтүүсүз эл аз."}'::jsonb, i18n = '{"ru":{"dayTitle":"Красные каньоны Конорчека","activities":["Пеший маршрут по красному каньону","Высокие глиняные образования"],"tips":["На тропе нет воды; возьмите минимум 2 литра."],"details":{"culture":"Красные глиняные каньоны, популярные для однодневных походов из Бишкека.","howToGetThere":"В Чуйской области рядом с Боомским ущельем, примерно в 2 часах к востоку от Бишкека."}},"ky":{"dayTitle":"Конорчектин кызыл капчыгайлары","activities":["Кызыл капчыгай менен жөө жүрүү","Бийик балчык формалар"],"tips":["Жолдо суу жок; кеминде 2 литр алыңыз."],"details":{"culture":"Бишкектен бир күндүк жөө сапарларга популярдуу кызыл балчык капчыгайлар.","howToGetThere":"Чүй облусунда, Боом капчыгайына жакын, Бишкектен чыгышка карай болжол менен 2 саатте."}}}'::jsonb where id = 'konorchek';
update public.destinations set description = '{"en":"Remains of the Karakhanid city of Balasagun: a minaret, balbal stones and a small museum.","ru":"Остатки караханидского города Баласагун: минарет, каменные фигуры балбал и небольшой музей.","ky":"Карахандид Баласагун шаарынын калдыктары: мунара, балбал таштар жана кичине музей."}'::jsonb, i18n = '{"ru":{"dayTitle":"Башня Бурана","activities":["Минарет XI века","Каменные фигуры балбал","Музей археологического объекта"],"tips":["По пути из Бишкека на Иссык-Куль."],"details":{"history":"Минарет XI века и остатки караханидского города Баласагун с каменными фигурами балбал.","howToGetThere":"Примерно в 80 км к востоку от Бишкека возле Токмока; часто останавливаются по дороге на Иссык-Куль."}},"ky":{"dayTitle":"Бурана мунарасы","activities":["XI кылымдагы мунара","Балбал таш фигуралар","Археологиялык объектинин музейи"],"tips":["Бишкек—Ысык-Көл жолундагы ыңгайлуу токтоо жери."],"details":{"history":"XI кылымдагы мунара жана балбал таштары бар карахандид Баласагун шаарынын калдыктары.","howToGetThere":"Бишкектен чыгышка карай болжол менен 80 км, Токмокко жакын; көбүнчө Ысык-Көлгө барар жолдо токтошот."}}}'::jsonb where id = 'burana';
commit;
